/** Convert the JSON generated by the staging secret to pg's connection URL. */
export function monitorSecretConnectionString(raw: string): string {
  function invalid(): never { throw new Error('Invalid monitor database secret.'); }
  let value: unknown;
  try { value = JSON.parse(raw); } catch { return invalid(); }
  if (!value || typeof value !== 'object' || Array.isArray(value)) return invalid();
  const { username, password, host, port, dbname } = value as Record<string, unknown>;
  if (typeof host !== 'string' || host.length > 253 || !host.split('.').every(
    label => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i.test(label),
  )) return invalid();
  if (typeof port !== 'number' || !Number.isInteger(port) || port < 1 || port > 65535 ||
    typeof username !== 'string' || !/^[a-z][a-z0-9_]{0,62}$/.test(username) ||
    typeof dbname !== 'string' || !/^[a-z][a-z0-9_]{0,62}$/.test(dbname) ||
    typeof password !== 'string' || !password || password.includes('\u0000')) return invalid();
  // Encode the literal secret, including '%' and reserved URL delimiters.
  const url = new URL('postgresql://localhost');
  url.hostname = host;
  url.port = String(port);
  url.pathname = '/' + dbname;
  url.username = username;
  url.password = encodeURIComponent(password);
  return url.href;
}
